-- ----------------------------
-- 表结构: books
-- ----------------------------
DROP TABLE IF EXISTS `books`;
CREATE TABLE "books" (
  "id" int NOT NULL AUTO_INCREMENT,
  "name" varchar(255) DEFAULT NULL,
  "type" varchar(255) DEFAULT NULL,
  "description" text,
  "aa" varchar(255) DEFAULT NULL,
  "bd" varchar(255) DEFAULT NULL,
  "ac" varchar(500) DEFAULT NULL,
  "ab" varchar(500) DEFAULT NULL,
  "ax" varchar(500) DEFAULT NULL,
  "user_id" bigint DEFAULT NULL,
  "create_time" datetime DEFAULT CURRENT_TIMESTAMP,
  "update_time" datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  "deleted" tinyint DEFAULT '0',
  "deleted_time" datetime DEFAULT NULL COMMENT '删除时间',
  "deleted_by" varchar(100) DEFAULT NULL COMMENT '删除操作人',
  PRIMARY KEY ("id"),
  KEY "idx_deleted" ("deleted"),
  KEY "idx_name" ("name"),
  KEY "idx_type" ("type"),
  KEY "idx_bd" ("bd"),
  KEY "idx_deleted_time" ("deleted","deleted_time")
);

